import { Group, Mesh, Color, FrontSide, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new Group();

  const visualSpec = config.intent?.visualSpec ?? {};
  const colors = visualSpec.colors ?? {};

  const ink = new Color(colors.ink || '#16161d');
  const paper = new Color(colors.paper || '#e8ecf2');
  const accent = new Color(colors.accent || '#ff2a38');
  const surface = new Color(colors.surface || '#0b0b10');

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textItem = items.find((item) => item.role === 'headline') || items[0];

  const atlasWidth = 512;
  const atlasHeight = 320;
  const aspect = atlasWidth / atlasHeight;

  const heightUnits = 0.5;
  const widthUnits = heightUnits * aspect;

  const geometry = new PlaneGeometry(widthUnits, heightUnits);
  const material = new MeshBasicNodeMaterial({
    color: surface,
    side: FrontSide,
    transparent: false,
  });

  const plane = new Mesh(geometry, material);
  plane.position.set(0, 0, 0);
  group.add(plane);

  let loadedTexture = null;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      loadedTexture = texture;
      material.color = new Color(0xffffff);
      material.map = texture;
      material.needsUpdate = true;
    }).catch(() => {});
  }

  if (textItem && textItem.text) {
    const label = ctx.fontAtlas.createText(String(textItem.text), {
      fontSize: textItem.typography?.fontSize ?? 39,
      color: paper,
      align: 'center',
      maxWidthPx: atlasWidth,
      letterSpacingPx: 2,
    });

    label.position.set(0, 0, 0.03);
    group.add(label);
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (loadedTexture) {
      loadedTexture.dispose();
    }
  };

  return group;
}
